import{asTrimmedNonEmptyString as asString}from"./utils/text.js";export const DEFAULT_USER_MESSAGE_PREFIX="User Message From Kimi:";export const GROUP_ROOM_MESSAGE_PREFIX="Message From Kimi Group Chat Room:";export const GROUP_ROOM_SENDER_SHORT_ID_LABEL="sender_short_id";export const resolveUserMessagePrefix=s=>asString(s)??"User Message From Kimi:";export const resolveImUserMessagePrefix=(s,e)=>asString(e)?GROUP_ROOM_MESSAGE_PREFIX:s;export const withUserMessagePrefix=(s,e)=>s.startsWith(e)?s:`${e}\n${s}`;export const withGroupRoomSenderShortId=(s,e)=>{const r=asString(e);if(!r)return s;const t=`[sender_short_id: ${r}]`,o=s.split(/\r?\n/);return o.some(s=>s.trim()===t)?s:o[0]===GROUP_ROOM_MESSAGE_PREFIX?[o[0],t,...o.slice(1)].join("\n"):[GROUP_ROOM_MESSAGE_PREFIX,t,s].join("\n")};